// Departmental source records for shared M30 planning. No new roles, scoring,
// placement offers, plan approvals or execution authority are created here.
const studentAffairsServiceAreas=Object.freeze({CLUB_EVENTS:'Club events and leadership',PLACEMENT_CAREER:'Placement and career services',INTERNSHIPS:'Internship coordination',LEADERSHIP_SKILLS:'Leadership, skills and student development',COMMUNITY_PARTNERSHIPS:'Community, SDG and partnership activities',PARTICIPATION_RECOGNITION:'Participation, recognition and follow-up'});
function studentAffairsPlanner(){return uid==='sa1'}
function studentAffairsUnitPlan(id){return (db.unitPlans||[]).find(p=>p.id===id&&p.unitCode==='STUDENT_AFFAIRS')}
function studentAffairsPlanControlled(p){return !!p?.approvalControl?.managed||(db.planApprovalRecords||[]).some(r=>{try{const s=JSON.parse(r.sourceBinding);return s.kind==='DEPARTMENTAL'&&s.id===p.id&&s.version===(p.version||1)&&s.content.source.record.id===p.id}catch{return false}})}
function studentAffairsDraftWritable(p){return studentAffairsPlanner()&&p?.owner===uid&&p.state==='DRAFT'&&!studentAffairsPlanControlled(p)}
function studentAffairsPlanLog(p,action){const r={time:new Date().toISOString(),actor:name(uid),action,project:p.id};p.history??=[];p.history.unshift(r);db.audit.unshift(r);save()}
function studentAffairsPlanForm(id){const p=id?studentAffairsUnitPlan(id):null;if(!studentAffairsPlanner()||(id&&!studentAffairsDraftWritable(p)))return;modal(`<h2>${p?'Edit':'Create'} Student Affairs department plan</h2><form onsubmit="saveStudentAffairsPlan(event,'${esc(id||'')}')">${field('title','Plan title',p?.title||'')}${field('cycle','Planning cycle',p?.cycle||'')}<label>Department objectives<textarea name="objectives" required maxlength="4000">${esc(p?.objectives||'')}</textarea></label><p>Draft plans receive no approval or execution authority. Programme areas share the protected responsible-unit → Finance Administrator → Principal plan review.</p><button class="primary">Save draft</button> <button type="button" onclick="closeModal()">Cancel</button></form>`)}
function saveStudentAffairsPlan(e,id){e.preventDefault();const p=id?studentAffairsUnitPlan(id):null,f=Object.fromEntries(new FormData(e.target));if(!studentAffairsPlanner()||(id&&!studentAffairsDraftWritable(p))||!String(f.title||'').trim()||f.title.length>200||!String(f.cycle||'').trim()||f.cycle.length>80||!String(f.objectives||'').trim()||f.objectives.length>4000)return toast('Use a writable draft and complete the title, cycle and objectives.');let plan=p;if(!plan){const key=clubKey('UP');plan={id:key,family:key,version:1,unitCode:'STUDENT_AFFAIRS',owner:uid,kind:'DEPARTMENTAL',state:'DRAFT',title:f.title.trim(),cycle:f.cycle.trim(),objectives:f.objectives.trim(),items:[],history:[]};db.unitPlans??=[];db.unitPlans.push(plan)}else Object.assign(plan,{title:f.title.trim(),cycle:f.cycle.trim(),objectives:f.objectives.trim()});studentAffairsPlanLog(plan,'Department plan draft saved; institutional review and execution are separate.');closeModal();render()}
function studentAffairsItemForm(planId,itemId){const p=studentAffairsUnitPlan(planId),i=p?.items.find(x=>x.id===itemId);if(!studentAffairsDraftWritable(p))return;modal(`<h2>${i?'Edit':'Add'} service programme / activity</h2><form onsubmit="saveStudentAffairsPlanItem(event,'${esc(planId)}','${esc(itemId||'')}')"><label>Service area<select name="serviceArea">${Object.entries(studentAffairsServiceAreas).map(([k,v])=>`<option value="${k}" ${i?.serviceArea===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label>${field('title','Programme / activity',i?.title||'')}${field('start','Start date',i?.start||'','date')}${field('end','End date',i?.end||'','date')}${field('responsible','Responsible person',i?.responsible||'')}${field('mentorEvaluator','Mentor / evaluator arrangement',i?.mentorEvaluator||'')}<label>Expected deliverable<textarea name="deliverable" required maxlength="2000">${esc(i?.deliverable||'')}</textarea></label>${field('kpi','KPI / measure',i?.kpi||'')}${field('target','Target',i?.target||'')}${field('budget','Planned budget (NPR)',i?.budget||'0')}${field('budgetReference','Budget / funding reference',i?.budgetReference||'')}<label>Evidence required<textarea name="evidence" required maxlength="2000">${esc(i?.evidence||'')}</textarea></label><p>Names and arrangements in this plan are planning declarations. They do not create an assignment, evaluator permission, placement selection or payment authority.</p><button class="primary">Save planned item</button> <button type="button" onclick="closeModal()">Cancel</button></form>`)}
function studentAffairsItemValid(i){return !!i&&Object.hasOwn(studentAffairsServiceAreas,i.serviceArea)&&['title','responsible','mentorEvaluator','deliverable','kpi','target','budgetReference','evidence'].every(k=>typeof i[k]==='string'&&i[k].trim()&&i[k].length<=(['deliverable','evidence'].includes(k)?2000:200))&&typeof i.start==='string'&&typeof i.end==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(i.start)&&/^\d{4}-\d{2}-\d{2}$/.test(i.end)&&Number.isFinite(Date.parse(i.start))&&Number.isFinite(Date.parse(i.end))&&new Date(i.start).toISOString().slice(0,10)===i.start&&new Date(i.end).toISOString().slice(0,10)===i.end&&i.start<=i.end&&/^\d+(?:\.\d{1,2})?$/.test(i.budget)&&Number.isSafeInteger(Math.round(Number(i.budget)*100))}
function saveStudentAffairsPlanItem(e,planId,itemId){e.preventDefault();const p=studentAffairsUnitPlan(planId),i=p?.items.find(x=>x.id===itemId),f=Object.fromEntries(new FormData(e.target));if(!studentAffairsDraftWritable(p)||(itemId&&!i))return toast('Only the current draft owner can change planned items.');for(const k of Object.keys(f))f[k]=f[k].trim();if(!studentAffairsItemValid(f))return toast('Complete the service area, dates, responsibilities, targets, budget reference and evidence requirements.');if(i)Object.assign(i,f);else p.items.push({id:clubKey('UPI'),...f});studentAffairsPlanLog(p,'Department service plan item '+(i?'updated':'added')+'; no execution or evaluator assignment created.');closeModal();render()}
function submitStudentAffairsPlan(e,id){e.preventDefault();const p=studentAffairsUnitPlan(id),f=Object.fromEntries(new FormData(e.target));if(!studentAffairsDraftWritable(p)||String(p.version)!==f.planVersion||f.confirm!=='yes'||!String(f.reason||'').trim()||f.reason.length>4000||!p.items.length||p.items.some(i=>!studentAffairsItemValid(i)))return toast('Confirm the current complete plan version with a submission reason.');p.state='SUBMITTED';p.submission={by:uid,at:new Date().toISOString(),reason:f.reason.trim(),planVersion:p.version};p.submissionRecords??=[];p.submissionRecords.push({...p.submission,action:'SUBMITTED'});studentAffairsPlanLog(p,'Department plan submitted for protected review; no approval, payment or execution authority granted.');closeModal();render()}
function studentAffairsSubmitForm(id){const p=studentAffairsUnitPlan(id);if(!studentAffairsDraftWritable(p))return;modal(`<h2>Submit department plan for review</h2><form onsubmit="submitStudentAffairsPlan(event,'${esc(id)}')"><input name="planVersion" type="hidden" value="${p.version}"><label>Submission reason<textarea name="reason" required maxlength="4000"></textarea></label><label style="display:flex;gap:8px"><input style="width:auto" name="confirm" type="checkbox" value="yes" required><span>Submit this exact version for the protected review route</span></label><p>Responsible-unit review → Finance Administrator → Principal. Named institutional source/reviewer mappings must be active before protected decisions can be recorded.</p><button class="primary">Submit for review</button> <button type="button" onclick="closeModal()">Cancel</button></form>`)}
function withdrawStudentAffairsPlanSubmission(e,id){e.preventDefault();const p=studentAffairsUnitPlan(id),f=Object.fromEntries(new FormData(e.target)),reason=String(f.reason||'').trim();if(!studentAffairsPlanner()||p?.owner!==uid||p.state!=='SUBMITTED'||studentAffairsPlanControlled(p)||String(p.version)!==f.planVersion||!reason||reason.length>4000||f.confirm!=='yes')return toast('Only an unlocked current submission may be withdrawn with a reason.');p.submissionRecords??=[];p.submissionRecords.push({action:'WITHDRAWN',by:uid,at:new Date().toISOString(),reason,planVersion:p.version});p.state='DRAFT';studentAffairsPlanLog(p,'Department submission withdrawn for draft correction; earlier submission retained.');closeModal();render()}
function studentAffairsWithdrawForm(id){const p=studentAffairsUnitPlan(id);if(!studentAffairsPlanner()||p?.owner!==uid||p.state!=='SUBMITTED'||studentAffairsPlanControlled(p))return;modal(`<h2>Withdraw pending department submission</h2><form onsubmit="withdrawStudentAffairsPlanSubmission(event,'${esc(id)}')"><input name="planVersion" type="hidden" value="${p.version}"><label>Reason<textarea name="reason" required maxlength="4000"></textarea></label><label><input style="width:auto" type="checkbox" name="confirm" value="yes" required>Return this unlocked version to draft for correction</label><p>Once protected institutional review starts, use that review's return/amendment route instead.</p><button class="primary">Withdraw submission</button></form>`)}
// Called by the server view before private intake/project filtering. Never grants case access.
function studentAffairsInternshipProjection(){
 if(!studentAffairsPlanner())return null;
 const counts={submittedIntakes:0,withdrawnIntakes:0,currentApprovedPlacements:0,currentApproachLetters:0,currentStartAuthorizations:0,executionWorkspaces:0,currentExecutionSources:0,changedExecutionSources:0,pausedOrCancelledWorkspaces:0,currentApprovedFinalReviews:0,unclassifiableRecords:0};
 const intakes=(db.activityIntakes||[]).filter(r=>r?.content?.type==='Internship'&&r.state!=='DRAFT'&&Array.isArray(r.submissions)&&r.submissions.length>0);
 for(const r of intakes){counts.submittedIntakes++;if(r.state==='WITHDRAWN'){counts.withdrawnIntakes++;continue}try{const placement=internshipLatest(r),readiness=internshipReadinessLatest(r);if(placement?.state==='APPROVED'&&internshipCurrent(r,placement))counts.currentApprovedPlacements++;if(internshipCurrentLetter(r))counts.currentApproachLetters++;if(readiness?.state==='START_AUTHORIZED'&&internshipReadinessCurrent(r,readiness))counts.currentStartAuthorizations++}catch{counts.unclassifiableRecords++}}
 for(const p of db.projects||[]){if(!p?.internshipProvenance)continue;counts.executionWorkspaces++;try{const current=internshipProjectCurrent(p);if(current)counts.currentExecutionSources++;else counts.changedExecutionSources++;if(!activityControlActive(p))counts.pausedOrCancelledWorkspaces++;if(current&&activityControlActive(p)&&internshipFinalApproved(p))counts.currentApprovedFinalReviews++}catch{counts.unclassifiableRecords++}}
 return {available:true,schema:'KCC360_SA_INTERNSHIP_SUMMARY_V1',scope:'OWNER_DEMO',counts,basis:'Submitted owner-demo internship intakes and linked execution workspaces. Counts overlap across stages; withdrawn intakes are excluded from current authorization counts. No eligible-cohort denominator, employment outcome, grade or academic credit is inferred.'};
}
function studentAffairsInternshipFacts(){return studentAffairsPlanner()&&db.studentAffairsInternshipSummary?.schema==='KCC360_SA_INTERNSHIP_SUMMARY_V1'?db.studentAffairsInternshipSummary:{available:false,reason:'The server internship summary is unavailable for this session.'}}
function studentAffairsInternshipPanel(){const summary=studentAffairsInternshipFacts();if(!summary.available)return '<section class="panel"><h2>Internship coordination</h2><p>Unavailable — '+esc(summary.reason)+'</p></section>';const c=summary.counts;return '<section class="panel" style="margin:20px 0"><h2>Internship coordination — workflow facts</h2>'+tableHTML(['Measure','Count'],[['Submitted intakes (including withdrawn)',c.submittedIntakes],['Withdrawn intakes',c.withdrawnIntakes],['Current approved placement proposals',c.currentApprovedPlacements],['Current approach letters',c.currentApproachLetters],['Current start authorizations',c.currentStartAuthorizations],['Linked execution workspaces',c.executionWorkspaces],['Execution workspaces with current sources',c.currentExecutionSources],['Execution workspaces with changed sources',c.changedExecutionSources],['Paused or cancelled execution workspaces',c.pausedOrCancelledWorkspaces],['Current independently approved final reviews',c.currentApprovedFinalReviews],['Records requiring classification review',c.unclassifiableRecords]].map(([label,count])=>[label,String(count)]))+'<p class="meta">'+esc(summary.basis)+'</p><p>Approach letters do not establish host acceptance or permission to start. Final reviews do not award grades or credit. Case records retain their existing permissions; this summary creates no case access or decision authority.</p></section>'}
function studentAffairsMonitoringFacts(){if(!studentAffairsPlanner())return null;const clubIds=new Set((db.clubs||[]).map(c=>c.id)),activities=db.projects.filter(p=>p.sourceClub&&clubIds.has(p.sourceClub)&&canSee(p)),waiting=activities.flatMap(p=>(p.members||[]).filter(id=>p.reflections?.[id]&&!p.evaluations?.[id]?.final)),clubEvaluations=(db.clubEvaluations||[]).filter(r=>clubEvaluationReader(clubById(r.clubId)));return {clubActivities:activities.length,verifiedClubActivities:activities.filter(verifiedActivity).length,openClubActivities:activities.filter(p=>!verifiedActivity(p)&&p.activityControl?.state!=='CANCELLED').length,awaitingIndividualEvaluation:waiting.length,annualEvaluationsAwaitingUnitReview:clubEvaluations.filter(r=>r.state==='SUBMITTED').length,placement:{available:false,reason:'The job-placement case workflow is not yet available.'},internships:studentAffairsInternshipFacts(),basis:'Existing readable owner-demo club records only; no whole-college placement or eligible-cohort denominator.'}}
function studentAffairsApprovedCalendarPanel(){if(!studentAffairsPlanner())return '';const calendar=db.studentAffairsApprovedCalendar;if(calendar?.schema!=='KCC360_APPROVED_CLUB_CALENDAR_V1')return '<section class="panel"><h2>Approved club activity calendar</h2><p>Unavailable — refresh the shared workspace to load the server calendar.</p></section>';return '<section class="panel" style="margin:20px 0"><h2>Approved club activity calendar</h2><p>Names and dates appear here after responsible-unit review, Finance Administrator review and Principal final approval.</p>'+ (calendar.events.length?tableHTML(['Club / annual cycle','Approved activity','Dates','Plan version / status'],calendar.events.map(i=>[esc(i.clubName)+'<br>'+esc(i.cycle),esc(i.title),esc(i.start)+' → '+esc(i.end),esc(i.planId)+' · v'+i.planVersion+'<br>Approved planning entry'])):'<p>No finally approved protected club activities are available. Drafts, unit endorsements and legacy approval labels are excluded. Institutional review configuration remains required.</p>')+'<p class="meta">'+esc(calendar.basis)+'</p>'+(calendar.withheldPlans?'<p class="notice">'+calendar.withheldPlans+' plan source(s) require reconciliation; their activities are withheld.</p>':'')+'</section>'}
function studentAffairsReviewLink(p){const query=new URLSearchParams({planId:p.id,planVersion:String(p.version)});return `<a class="button" href="/workspace/plan-approvals.html?${esc(query.toString())}" target="_blank" rel="noopener">Open protected plan review</a>`}
function studentAffairsPage(){if(!studentAffairsPlanner())return heading('Student Affairs','Department planning is outside the current demo role.')+'<div class="notice">Use an authorized departmental assignment. Selecting a page grants no permission.</div>';const plans=(db.unitPlans||[]).filter(p=>p.unitCode==='STUDENT_AFFAIRS'),facts=studentAffairsMonitoringFacts();return heading('Student Affairs department','Plan, monitor and review the departmental service portfolio.',btn('+ Department plan','studentAffairsPlanForm()','primary'))+`<div class="notice">Department plans and club plans use responsible-unit review → Finance Administrator → Principal. Draft or submitted targets do not authorize events, placements, payments or individual evaluation. This workspace remains an owner-only demonstration.</div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(240px,1fr))">${Object.entries(studentAffairsServiceAreas).map(([k,label])=>{const items=plans.flatMap(p=>p.items.filter(i=>i.serviceArea===k));return `<div class="card"><h3>${esc(label)}</h3><p>${items.length} planned item${items.length===1?'':'s'} across the department plans shown below.</p><p class="meta">Planning entries include draft/submitted work; this is not a completed-service count.</p></div>`}).join('')}</div><section class="panel" style="margin:20px 0"><h2>Monitoring — available facts</h2>${tableHTML(['Measure','Value / status'],[['Readable club activities',String(facts.clubActivities)],['Verified club activities',String(facts.verifiedClubActivities)],['Open club activities',String(facts.openClubActivities)],['Submitted reflections awaiting final evaluation',String(facts.awaitingIndividualEvaluation)],['Annual club evaluations awaiting unit review',String(facts.annualEvaluationsAwaitingUnitReview)],['Job placement outcomes','Unavailable — '+esc(facts.placement.reason)],['Institution-wide internship outcomes','Unavailable — no official eligible-cohort denominator or MIS outcome reconciliation.']])}<p class="meta">${esc(facts.basis)} Counts show workflow facts, not a performance rating or an individual student score.</p><div class="buttons">${btn('Club workspaces',"go('Clubs')")}${btn('Annual evaluation',"go('Club Evaluation')")}${btn('Existing authorized reports',"go('Reports')")}</div></section>${studentAffairsInternshipPanel()}${studentAffairsApprovedCalendarPanel()}${plans.map(p=>`<section class="panel" style="margin:20px 0"><div class="top"><div><h2>${esc(p.title)}</h2><p>${esc(p.cycle)} · ${esc(p.id)} · v${p.version}</p></div>${pill(p.state)}</div><p>${esc(p.objectives)}</p><p class="meta">Owner: ${esc(name(p.owner))} · ${studentAffairsPlanControlled(p)?'Protected source locked; generic edits disabled.':'Preparation/submission status only; protected approval decisions are separate.'}</p>${p.approvalControl?.reviewState?'<p>Protected review: '+esc(label(p.approvalControl.reviewState))+' · New execution is not authorized.</p>':''}<div class="buttons">${studentAffairsDraftWritable(p)?btn('Edit plan',`studentAffairsPlanForm('${p.id}')`)+btn('+ Service item',`studentAffairsItemForm('${p.id}')`)+btn('Submit for review',`studentAffairsSubmitForm('${p.id}')`,'primary'):''}${p.state==='SUBMITTED'&&!studentAffairsPlanControlled(p)?btn('Withdraw for correction',`studentAffairsWithdrawForm('${p.id}')`):''}${studentAffairsReviewLink(p)}</div>${tableHTML(['Service / planned activity','Dates / responsibility','Deliverable / KPI / target','Budget reference','Evidence / arrangement','Action'],p.items.map(i=>[esc(studentAffairsServiceAreas[i.serviceArea])+'<br><strong>'+esc(i.title)+'</strong>',esc(i.start)+' → '+esc(i.end)+'<br>'+esc(i.responsible),esc(i.deliverable)+'<br>'+esc(i.kpi)+' · '+esc(i.target),'NPR '+esc(i.budget)+'<br>'+esc(i.budgetReference),esc(i.evidence)+'<br>'+esc(i.mentorEvaluator),studentAffairsDraftWritable(p)?btn('Edit',`studentAffairsItemForm('${p.id}','${i.id}')`):'Locked']))}<details><summary>Plan preparation history</summary>${history(p.history||[])}</details></section>`).join('')||'<div class="panel">No department plans have been created. Add a plan and service items; the system does not prepopulate targets or actual outcomes.</div>'}`}
const studentAffairsPriorRender=render;
render=function(){const requested=page==='Student Affairs';if(requested)page='Overview';studentAffairsPriorRender();if(requested){$('#nav').innerHTML=$('#nav').innerHTML.replace('class="active"','class=""');page='Student Affairs';$('#crumb').textContent='STUDENT AFFAIRS';$('#app').innerHTML=studentAffairsPage()}if(studentAffairsPlanner())$('#nav').innerHTML=btn('◇   Student Affairs',"go('Student Affairs')",requested?'active':'')+$('#nav').innerHTML};
